import math
import re

PRIMARY, SECONDARY = "\u02c8", "\u02cc"
PUNCTUATION = ".,;:!?"
SWITCH = re.compile(r"\(([a-z]{2,3})\)")


def strip_language_switches(stream):
    found = SWITCH.findall(stream)
    cleaned = re.sub(r"\s*" + SWITCH.pattern + r"\s*", " ", stream).strip()
    return re.sub(r"\s+", " ", cleaned), found


def parse_phonemes(stream, with_stress=True, preserve_punctuation=True):
    cleaned, _ = strip_language_switches(stream)
    tokens = []
    for word in cleaned.split():
        trailing = ""
        while word and word[-1] in PUNCTUATION:
            trailing = word[-1] + trailing
            word = word[:-1]
        stress = None
        if PRIMARY in word:
            stress = "primary"
        elif SECONDARY in word:
            stress = "secondary"
        bare = word.replace(PRIMARY, "").replace(SECONDARY, "")
        if not bare:
            continue
        tokens.append({
            "phonemes": bare if with_stress is False else word,
            "stress": stress if with_stress else None,
            "trailing": trailing if preserve_punctuation else "",
        })
    return tokens


def phoneme_vocabulary(streams, with_stress=True):
    symbols = set()
    for stream in streams:
        for token in parse_phonemes(stream, with_stress=with_stress,
                                    preserve_punctuation=False):
            symbols.update(token["phonemes"])
    return sorted(symbols)


def pulse_train(f0, sample_rate, n):
    period = int(sample_rate / f0)
    return [1.0 if index % period == 0 else 0.0 for index in range(n)]


def resonator(source, freq, sample_rate, bandwidth=90.0):
    r = math.exp(-math.pi * bandwidth / sample_rate)
    w = 2 * math.pi * freq / sample_rate
    a1 = 2 * r * math.cos(w)
    a2 = -(r * r)
    out = []
    previous, before = 0.0, 0.0
    for sample in source:
        value = sample + a1 * previous + a2 * before
        out.append(value)
        before, previous = previous, value
    return out
